#!/usr/bin/env bash
# Environment for the PRIA joint-replenishment experiments.  Source it, do not
# execute it:
#
#     source env.sh
#
# This file is the single home for every path the project uses.  Nothing else
# in the repository hard-codes one; scripts read these variables and fail
# loudly if a required one is missing.
#
# To use your own paths, do NOT edit this file -- copy env.local.sh.example to
# env.local.sh and set them there.  env.local.sh is gitignored, so your paths
# never show up in a diff.  Anything already exported in your shell also wins,
# because every assignment below is a ":=" default.

# --- repository root -------------------------------------------------------
# Resolved from this file's own location, so the repo can live anywhere.  bash
# and zsh name the sourced file differently, and zsh's spelling is a syntax
# error to bash's parser -- hence the eval, which keeps each shell from having
# to parse the other's form.
if [ -n "${ZSH_VERSION:-}" ]; then
    eval '_pria_self=${(%):-%x}'
else
    _pria_self="${BASH_SOURCE[0]:-$0}"
fi
PRIA_ROOT="$(cd "$(dirname "$_pria_self")" && pwd)"
unset _pria_self
export PRIA_ROOT

# --- results, binaries -----------------------------------------------------
# The defaults are gitignored directories at the repository root, so a fresh
# clone works with no configuration at all.  Point them at scratch or network
# storage in env.local.sh when the results get large.
: "${PRIA_RESULTS_DIR:=$PRIA_ROOT/results}"  # benchmark output (CSV)
: "${PRIA_BIN_DIR:=$PRIA_ROOT/bin}"          # compiled CUDA binaries
export PRIA_RESULTS_DIR PRIA_BIN_DIR

# --- python ----------------------------------------------------------------
# The interpreter that has jax, numpy, scipy and (for the Gurobi backend)
# gurobipy.  A plain "python3" is the portable default; override it in
# env.local.sh if your environment lives elsewhere.
: "${PRIA_PYTHON:=python3}"
export PRIA_PYTHON

# --- cuPDLPx ---------------------------------------------------------------
# Checkout of https://github.com/MIT-Lu-Lab/cuPDLPx.  The backend imports its
# Python package rather than running a binary, so only the checkout is named
# here -- for building the wheel against the right architecture.  On a machine
# without it the backend reports "unavailable" rather than failing the run.
: "${CUPDLPX_DIR:=$PRIA_ROOT/../cuPDLPx}"
export CUPDLPX_DIR

# --- Gurobi ----------------------------------------------------------------
# GRB_LICENSE_FILE is only needed if gurobipy cannot find a licence on its
# own.  GUROBI_THREADS pins Gurobi's thread pool to the job's allocation: it
# sizes the pool from the whole machine rather than from the cgroup, so under
# a scheduler it oversubscribes.  Neither has a default here -- an unset
# variable is the "leave it alone" case, and what that means is
# harness/config.py's to say, not this file's.
: "${GRB_LICENSE_FILE:=}"
[ -n "$GRB_LICENSE_FILE" ] && export GRB_LICENSE_FILE
[ -n "${GUROBI_THREADS:-}" ] && export GUROBI_THREADS

# --- local overrides -------------------------------------------------------
# Sourced so it wins over everything above, and before the CUDA block below,
# whose values are derived from what it sets.
if [ -f "$PRIA_ROOT/env.local.sh" ]; then
    # shellcheck source=/dev/null
    . "$PRIA_ROOT/env.local.sh"
fi

# --- CUDA ------------------------------------------------------------------
# CUDA_HOME is only needed when building pria-cuda or cuPDLPx.  CUDA_ARCH has
# no default anywhere else: pria-cuda/Makefile deliberately refuses to guess,
# so this line is the only place the target SM is chosen.  NVCC follows
# CUDA_HOME, a module load in env.local.sh being one of the things that sets
# it, so both are settled after the overrides rather than before them.
: "${CUDA_HOME:=/usr/local/cuda}"
: "${NVCC:=$CUDA_HOME/bin/nvcc}"
: "${CUDA_ARCH:=89}"                          # 89 = L40S / Ada; 80 = A100; 90 = H100
export CUDA_HOME NVCC CUDA_ARCH

mkdir -p "$PRIA_RESULTS_DIR" "$PRIA_BIN_DIR" "$PRIA_ROOT/logs"
